// Get all rows returned by the Postgres node
const currentMessages = $input.all().map(item => item.json);

// Normalize names for the Epistemologist JSON schema
const getFullName = (shortName) => {
  if (shortName === 'neuro') return 'NEUROSCIENTIST';
  if (shortName === 'psych') return 'PSYCHOLOGIST';
  if (shortName === 'physio') return 'PHYSIOLOGIST';
  return shortName.toUpperCase();
};

// Format the claims into a structured text block for the prompt
let formattedClaims = "### CURRENT EXPERT CLAIMS FOR REVIEW ###\n\n";

currentMessages.forEach(msg => {
  formattedClaims += `--- ${getFullName(msg.agent_name)} ---\n${msg.content}\n\n`;
});

// Create the final payload to pass directly to the Agent
return [{
  json: {
    session_id: $('Payload').first().json.session_id,
    current_iteration:$('Payload').first().json.current_iteration ,
    user_query: $('Payload').first().json.user_query,
    expert_claims_text: formattedClaims
  }
}];

